  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'Os números dos gráficos não foram guardados — só existem nesta janela:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'No navegador não existe recuperação após falha: se fechar este separador, o trabalho não guardado desaparece. Guarde a sua apresentação por si.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  A base de dados CVE local (é você que inicia a transferência): o OciDeck obtém os dados em massa através de api.github.com e do ficheiro de lançamento para o qual esse endereço aponta.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  Pesquisa de CVE (desativada por predefinição): quando está ativa, o seu termo de pesquisa vai para o espelho CVE configurado e, se este não encontrar nada, para a base de dados europeia da ENISA e para a MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Um vídeo do YouTube ou do Vimeo incorporado carrega o leitor a partir desse serviço.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  No navegador: se o navegador recusar obter um endereço diretamente, o OciDeck tenta de novo através do servidor de onde a aplicação veio; esse endereço chega então a esse servidor.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'A revogação não foi guardada. No próximo arranque o seu consentimento volta a ser válido.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'Um subtítulo de secção que anuncia uma nova parte da apresentação. Seja breve. Adicione uma imagem de fundo a partir da biblioteca de imagens.',
  'Bronnen doorzoeken…': 'A pesquisar nas fontes…',
  'Niet doorzocht': 'Não pesquisado',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Esta verificação não é executada na versão web: a deteção de rostos precisa de uma biblioteca de sistema que o navegador não tem. Use a versão para computador para verificar rostos nas imagens.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'O token precisa de acesso de leitura e escrita ao repositório. Gitea e Forgejo não têm pesquisa no servidor; o OciDeck pesquisa localmente.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'O token precisa do escopo repo (ou detalhado: Contents de leitura e escrita).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'O token precisa de read_repository, write_repository e read_api. A pesquisa no servidor requer Advanced ou Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Pesquisa rápida no servidor — devido ao atraso de indexação, um deck alterado há pouco pode faltar.',
  'Media blijft niet bewaard in een los .md-bestand':
      'A multimédia não é mantida num ficheiro .md simples',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'As imagens, o vídeo e o áudio que escolheu neste separador existem apenas na memória. Um ficheiro .md simples não os mantém — desaparecem ao reabrir. Exporte como pacote .ocideck para levar a multimédia consigo.',
