  'Certificaat vertrouwen?': 'Confiar neste certificado?',
  'Het certificaat van deze server is niet ondertekend door een erkende uitgever. Dat is gewoon bij een zelf gehoste server, maar het is ook hoe een afgeluisterde verbinding eruitziet.':
      'O certificado deste servidor não está assinado por uma entidade reconhecida. Isso é normal num servidor próprio, mas é também o aspeto de uma ligação intercetada.',
  'Vergelijk de vingerafdruk hieronder met wat je server zelf toont. Komen ze overeen, dan praat je met de juiste machine.':
      'Compara a impressão digital abaixo com a que o teu servidor mostra. Se coincidirem, estás a falar com a máquina certa.',
  'Uitgegeven aan': 'Emitido para',
  'Uitgegeven door': 'Emitido por',
  'Geldig tot': 'Válido até',
  'Vingerafdruk (SHA-256)': 'Impressão digital (SHA-256)',
  'Alleen dit ene certificaat wordt vertrouwd. Vervangt de server het later, dan vraagt OciDeck het opnieuw.':
      'Apenas este certificado é fidedigno. Se o servidor o substituir mais tarde, o OciDeck perguntará de novo.',
  'Vertrouwen': 'Confiar',
  'Certificaat bekijken': 'Ver certificado',
  'De plekken waar je presentaties bewaart en doorzoekt — mappen op deze computer, WebDAV-servers, S3-buckets en git-repositories door elkaar. Sleep ze in de volgorde die jij wilt: de bovenste van een soort geldt als standaard.':
      'Os sítios onde guardas e pesquisas as tuas apresentações — pastas neste computador, servidores WebDAV, buckets S3 e repositórios git misturados. Arrasta-os pela ordem que quiseres: o primeiro de cada tipo vale como predefinição.',
  '•  S3-opslag: verbind je met een bucket, dan worden het endpoint, de bucketnaam en je toegangssleutel bewaard (de geheime sleutel veilig in de sleutelbos van je systeem) en worden de presentaties die je opent of opslaat naar die opslagdienst verstuurd.':
      '•  Armazenamento S3: quando te ligas a um bucket, são guardados o endpoint, o nome do bucket e a tua chave de acesso (a chave secreta em segurança no porta-chaves do teu sistema) e as apresentações que abres ou guardas são enviadas para esse serviço de armazenamento.',
  '•  Git-opslag: verbind je met een repository, dan wordt je toegangstoken bewaard (veilig in de sleutelbos van je systeem) en worden de presentaties die je opslaat als commits naar die server verstuurd. Een werkkopie van de repository blijft onversleuteld op dit apparaat staan.':
      '•  Armazenamento Git: quando te ligas a um repositório, é guardado o teu token de acesso (em segurança no porta-chaves do teu sistema) e as apresentações que guardas são enviadas para esse servidor como commits. Uma cópia de trabalho do repositório permanece não cifrada neste dispositivo.',
  'Voor de taal van dit deck ontbreken de ziekte- en aandoeningsnamen. Religie, politieke overtuiging en vakbondstermen worden wel herkend, en controlegetallen (BSN, IBAN, paspoort) werken altijd — maar reken er niet op dat een diagnose gevonden wordt.':
      'Faltam os nomes de doenças para o idioma desta apresentação. Religião, opinião política e termos sindicais são reconhecidos, e os padrões com dígito de controlo (NIF, IBAN, passaporte) funcionam sempre — mas não conte com a deteção de um diagnóstico.',
  'niet getest': 'não testada',
  'Werkte op': 'Funcionou em',
  'Je bent aangemeld, maar hebt hier geen toegang. Je wachtwoord is niet het probleem — vraag de beheerder om rechten op deze map.':
      'Tens sessão iniciada, mas não tens acesso aqui. A tua palavra-passe não é o problema — pede ao administrador permissões nesta pasta.',
  'Je token is geldig, maar mag dit niet. Geef het meer rechten, of wacht als de forge een limiet oplegt.':
      'O teu token é válido, mas não tem permissão para isto. Dá-lhe mais permissões, ou espera se a forge estiver a aplicar um limite.',
  'Het token is geldig, maar mag dit niet — geef het meer rechten op de repository.':
      'O token é válido, mas não tem permissão para isto — dá-lhe mais permissões no repositório.',
  'Aangemeld, maar geen toegang — je wachtwoord is niet het probleem. Vraag rechten op deze map.':
      'Com sessão iniciada, mas sem acesso — a tua palavra-passe não é o problema. Pede permissões nesta pasta.',
  'Dit lijkt een volledige DAV-URL. Bij Nextcloud leidt OciDeck dat pad zelf af — hier hoort alleen de server te staan.':
      'Isto parece um URL DAV completo. No Nextcloud, o OciDeck deduz esse caminho sozinho — aqui só pertence o servidor.',
  'Overnemen': 'Aplicar',
  'WebDAV is niet (goed) ingesteld — controleer de servergegevens bij Instellingen → Opslag.':
      'O WebDAV não está (bem) configurado — verifica os dados do servidor em Definições → Armazenamento.',
  'De git-repository is niet (goed) ingesteld — controleer server, eigenaar en repository bij Instellingen → Opslag.':
      'O repositório git não está (bem) configurado — verifica servidor, proprietário e repositório em Definições → Armazenamento.',
  'De servernaam van de forge bestaat niet, of is niet op te zoeken. Controleer de server-URL op een typefout.':
      'O nome do servidor da forge não existe ou não pode ser consultado. Verifica se há uma gralha no URL do servidor.',
  'Deze forge heeft een privé- of LAN-adres. Markeer hem als vertrouwd intern bij Instellingen → Opslag.':
      'Esta forge tem um endereço privado ou de LAN. Marca-a como interna fidedigna em Definições → Armazenamento.',
  'De forge is niet bereikbaar — controleer je verbinding en de server-URL.':
      'A forge está inacessível — verifica a tua ligação e o URL do servidor.',
  'Aanmelden bij de forge mislukt. Controleer je token: het heeft leesrechten op de repository nodig, en schrijfrechten om op te slaan.':
      'A autenticação na forge falhou. Verifica o teu token: precisa de acesso de leitura ao repositório e de escrita para gravar.',
  'Niet gevonden in de repository — of je token mag het niet zien.':
      'Não encontrado no repositório — ou o teu token não o pode ver.',
  'De forge gaf een fout. Probeer het later opnieuw.':
      'A forge devolveu um erro. Tenta novamente mais tarde.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge bij Instellingen → Opslag?':
      'Este endereço não responde como uma forge. O tipo de forge em Definições → Armazenamento está correto?',
  'Stel eerst een WebDAV-server in bij Instellingen → Opslag.':
      'Configura primeiro um servidor WebDAV em Definições → Armazenamento.',
  'Nodig wanneer de forge op een privé- of thuisnetwerk draait. Zonder deze vlag weigert de beveiliging een privé-adres.':
      'Necessário quando a forge corre numa rede privada ou doméstica. Sem esta opção, a verificação de segurança recusa um endereço privado.',
  'Vul server-URL, eigenaar en repository in':
      'Preenche o URL do servidor, o proprietário e o repositório',
  'de standaardbranch heet': 'o ramo predefinido chama-se',
  'die wordt voortaan gebruikt': 'passará a ser usado esse',
  'de repository is nog leeg; de eerste opslag vult hem':
      'o repositório ainda está vazio; a primeira gravação irá preenchê-lo',
  'let op: dit token mag alleen lezen, dus opslaan zal mislukken':
      'atenção: este token só pode ler, por isso gravar irá falhar',
  'Aanmelden mislukt — controleer het token. Het heeft leesrechten op de repository nodig, en schrijfrechten om te kunnen opslaan.':
      'A autenticação falhou — verifica o token. Precisa de acesso de leitura ao repositório e de escrita para poder gravar.',
  'Repository niet gevonden — of je token mag hem niet zien. Controleer eigenaar en repositorynaam.':
      'Repositório não encontrado — ou o teu token não o pode ver. Verifica o proprietário e o nome do repositório.',
  'Dit adres antwoordt niet als een forge. Klopt de soort forge die je hebt gekozen?':
      'Este endereço não responde como uma forge. O tipo de forge que escolheste está correto?',
  'kenteken': 'matrícula do veículo',
  'Voor de taal van dit deck is er geen trefwoordenlijst voor bijzondere persoonsgegevens. Patronen met een controlegetal (BSN, IBAN, paspoort) werken wel; woorden als "diagnose" of "verdachte" worden niet herkend.':
      'Não existe lista de palavras-chave para categorias especiais de dados pessoais no idioma desta apresentação. Os padrões com dígito de controlo (NIF, IBAN, passaporte) funcionam; palavras como "diagnóstico" ou "suspeito" não são reconhecidas.',
  'Landpakketten voor identificatienummers':
      'Pacotes de país para números de identificação',
  'Nummers als het BSN of het PESEL zijn landgebonden. Heel Europa staat aan omdat de meeste van die nummers een controlegetal hebben: die aanzetten kost vrijwel geen valse meldingen. IBAN, e-mail, geheimen en paspoortstroken staan hier los van en worden altijd nagekeken.':
      'Números como o BSN neerlandês ou o PESEL polaco são específicos de cada país. Toda a Europa está ativa porque a maioria desses números tem um dígito de controlo: ativá-los quase não custa alertas falsos. IBAN, e-mail, segredos e faixas de passaporte são independentes disto e são sempre verificados.',
